<?php
// نصب‌کنندهٔ پنل مهریار: یک‌بار اجرا می‌شود، پوشهٔ panel را می‌سازد و بعد خودش را پاک می‌کند.
error_reporting(E_ALL);
ini_set('display_errors', '0');
header('Content-Type: text/html; charset=utf-8');
header('Cache-Control: no-store');

$F = array(
  'api.php' => '',
  'lib.php' => '',
  'admin.php' => '',
  'data.htaccess' => 'UmVxdWlyZSBhbGwgZGVuaWVkCkRlbnkgZnJvbSBhbGwK',
  'uploads.htaccess' => 'PEZpbGVzTWF0Y2ggIlwuKHBocHxwaHRtbHxwaGFyKSQiPgpSZXF1aXJlIGFsbCBkZW5pZWQKPC9GaWxlc01hdGNoPgo='
);

$root = __DIR__ . '/panel';
$log = array();
$ok = true;

function L($good, $msg) { global $log; $log[] = array($good, $msg); }
function put($path, $data) {
  $d = dirname($path);
  if (!is_dir($d) && !@mkdir($d, 0755, true)) return false;
  return @file_put_contents($path, $data) !== false;
}

if (version_compare(PHP_VERSION, '7.0.0', '<')) {
  $ok = false; L(false, 'نسخهٔ PHP هاست (' . PHP_VERSION . ') قدیمی است؛ حداقل ۷٫۰ لازم است.');
} else {
  L(true, 'نسخهٔ PHP: ' . PHP_VERSION);
}
if (!extension_loaded('pdo_sqlite')) {
  $ok = false; L(false, 'افزونهٔ SQLite (pdo_sqlite) روی PHP هاست روشن نیست.');
} else {
  L(true, 'SQLite روی هاست فعال است');
}

// اگر پنل قبلاً نصب شده، همان نام پایگاه‌داده حفظ می‌شود تا آمار پاک نشود
$db = null;
$old = @file_get_contents($root . '/lib.php');
$upd = ($old !== false);
if ($old !== false && preg_match('~data/(panel[-0-9a-f]*\.sqlite)~', $old, $m)) $db = $m[1];
if (!$db) {
  $r = function_exists('random_bytes') ? bin2hex(random_bytes(8)) : md5(uniqid('', true));
  $db = 'panel-' . $r . '.sqlite';
}

if ($ok) {
  $jobs = array(
    'api.php'           => base64_decode($F['api.php']),
    'lib.php'           => str_replace('data/panel.sqlite', 'data/' . $db, base64_decode($F['lib.php'])),
    'admin.php'         => base64_decode($F['admin.php']),
    'data/.htaccess'    => base64_decode($F['data.htaccess']),
    'uploads/.htaccess' => base64_decode($F['uploads.htaccess']),
    'index.html'        => '',
    'data/index.html'   => '',
    'uploads/index.html'=> ''
  );
  foreach ($jobs as $name => $data) {
    if (put($root . '/' . $name, $data)) L(true, 'ساخته شد: panel/' . $name);
    else { $ok = false; L(false, 'نتوانستم بسازم: panel/' . $name); }
  }
}

if ($ok) {
  foreach (array('data', 'uploads') as $d) {
    if (is_dir($root . '/' . $d) && is_writable($root . '/' . $d)) L(true, 'پوشهٔ ' . $d . ' قابل نوشتن است');
    else { $ok = false; L(false, 'پوشهٔ ' . $d . ' قابل نوشتن نیست'); }
  }
}

if ($ok) {
  try {
    require_once $root . '/lib.php';
    q('CREATE TABLE IF NOT EXISTS _t(x)');
    q('INSERT INTO _t VALUES(1)');
    q('DELETE FROM _t');
    L(true, 'پایگاه‌داده کار می‌کند');
  } catch (Throwable $e) {
    $ok = false;
    L(false, 'پایگاه‌داده خطا داد: ' . substr($e->getMessage(), 0, 120));
  }
}

$deleted = false;
if ($ok) $deleted = @unlink(__FILE__);

$https = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off') || (($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https');
$host = preg_replace('~[^a-zA-Z0-9.:\-]~', '', $_SERVER['HTTP_HOST'] ?? '');
$dirurl = rtrim(str_replace('\\', '/', dirname($_SERVER['SCRIPT_NAME'] ?? '/')), '/');
$base = ($https ? 'https' : 'http') . '://' . $host . $dirurl . '/panel';
$e = function ($s) { return htmlspecialchars($s, ENT_QUOTES, 'UTF-8'); };
?><!doctype html>
<html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>نصب پنل مهریار</title></head>
<body style="font:16px/2 system-ui,Tahoma,sans-serif;max-width:560px;margin:16px auto;padding:0 14px">
<h2><?php echo $ok ? ($upd ? '✅ پنل به‌روز شد' : '✅ پنل نصب شد') : '❌ نصب کامل نشد'; ?></h2>
<?php foreach ($log as $row) echo '<div>' . ($row[0] ? '✅ ' : '❌ ') . $e($row[1]) . '</div>'; ?>
<?php if ($ok): ?>
<hr>
<p><b>آدرس پنل (همین را در panel-test.html بزن):</b></p>
<p dir="ltr" style="background:#f3f3f3;padding:10px;border-radius:8px;word-break:break-all"><?php echo $e($base); ?></p>
<?php if (!$https): ?><p>⚠️ این آدرس <b>https</b> نیست. اپ و APK فقط با https درست کار می‌کنند؛ اول SSL سایت را فعال کن.</p><?php endif; ?>
<?php if ($upd): ?>
<p><b>قدم بعد:</b></p>
<ol>
<li><a href="<?php echo $e($base); ?>/admin.php">وارد پنل مدیریت شو</a> (رمز قبلی کار می‌کند).</li>
<li>در بخش <b>کلیدها</b> کلیدهای Gemini را بچسبان (هر کلید در یک خط) و برای هر کدام «تست» را بزن.</li>
<li>در بخش <b>کدها</b> برای هر معلم یک کد بساز و برایش بفرست.</li>
<li><a href="<?php echo $e($base); ?>/api.php?a=cfg">این لینک</a> باید همچنان تنظیمات پاپ‌آپ را نشان بدهد.</li>
<li><a href="<?php echo $e($base); ?>/data/">این لینک</a> باید خطا یا صفحهٔ خالی نشان بدهد (فهرست فایل نباشد).</li>
</ol>
<?php else: ?>
<p><b>قدم بعد:</b></p>
<ol>
<li><a href="<?php echo $e($base); ?>/admin.php">وارد پنل مدیریت شو</a> و <b>همین الان</b> رمز مدیر را بگذار (اولین نفری که وارد شود رمز را تعیین می‌کند).</li>
<li><a href="<?php echo $e($base); ?>/api.php?a=cfg">این لینک</a> باید متنی شبیه <span dir="ltr">{"banners":{},"popup":null}</span> نشان دهد.</li>
<li><a href="<?php echo $e($base); ?>/data/">این لینک</a> باید یک صفحهٔ خطا یا صفحهٔ خالی نشان دهد (ممنوع، ۴۰۳، ۴۰۴ یا ۵۰۰، هر کدام مشکلی ندارد). اگر فهرست فایل‌ها یا دانلود دیدی، فوراً به من بگو.</li>
<li>بعد panel-test.html را روی گوشی باز کن و آدرس بالا را در آن بزن.</li>
</ol>
<?php endif; ?>
<p><?php echo $deleted ? 'فایل نصب‌کننده خودش را پاک کرد.' : '⚠️ فایل install.php خودش پاک نشد؛ لطفاً آن را از هاست پاک کن.'; ?></p>
<?php else: ?>
<hr><p>پیام‌های ❌ بالا را برای من بفرست (عکس صفحه هم کافی است). تا این مشکل برطرف نشود، install.php را پاک نکن.</p>
<?php endif; ?>
</body></html>
